import { useContexState } from '../hooks/context'

export function useLoadPage() {

    const {
        loading,
        page,
        total,
    } = useContexState();

    const {
        setFeed,
        setLoading,
        setPage,
    } = useContexState();

    interface NumbersType {
        lineCards: number;
        id: string;
    }

    const cards = [
        {
            'number': '544',
            'name': 'Fabio_Vieira_Moraes',
            'date': '18/10/2021',
            'phone': '(18)9981-34184',
            'state': 'analysis',
        },
        {
            'number': '4544',
            'name': 'User_1',
            'date': '18/10/2021',
            'phone': '(18)9981-34184',
        },
        {
            'number': '344',
            'name': 'User_2',
            'date': '18/10/2021',
            'phone': '(18)9981-34184',
            'state': 'analysis',
        },
        {
            'number': '1204',
            'name': 'User_3',
            'date': '18/10/2021',
            'phone': '(18)9981-34184',
            'state': 'analysis',
        },
        {
            'number': '54',
            'name': 'User_4',
            'date': '18/10/2021',
            'phone': '(18)9981-34184',
            'state': 'analysis',
        },
    ];


    function LoadPage(value: string | number = 0) {

        if (page === total) return;
        if (loading) return;

        setLoading(true);

        const perPage = 84;
        const numbers: NumbersType[] = []

        for (let i = 0; i < perPage; i++) {
            numbers.push({ lineCards: (i * 6) + Number(value), id: String(i) })
        }

        setLoading(false);
        setPage(page + 1);
        setFeed([...numbers]);
    }

    return { LoadPage }
}
